<script>
(()=>{if(window.__giftchetaCatalogColumns)return;window.__giftchetaCatalogColumns=true;const allowsFour=()=>!window.matchMedia('(min-width: 1200px) and (max-width: 1399px)').matches;function setColumns(value,updateUrl=true){const max=allowsFour()?4:3,columns=Math.max(1,Math.min(max,Number(value)||3)),grid=document.querySelector('.catalog-results .product-grid');if(grid)grid.dataset.columns=String(columns);document.querySelectorAll('[data-catalog-columns]').forEach(button=>{const active=Number(button.dataset.catalogColumns)===columns;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active))});const hidden=document.querySelector('[data-live-catalog-filters] input[name="columns"]');if(hidden)hidden.value=String(columns);if(updateUrl){const url=new URL(location.href);url.searchParams.set('columns',String(columns));url.searchParams.delete('page');history.pushState({},'',url.pathname+url.search)}}function syncColumns(){const grid=document.querySelector('.catalog-results .product-grid');if(!grid)return;const url=new URL(location.href),requested=Number(url.searchParams.get('columns'))||Number(grid.dataset.columns)||3,max=allowsFour()?4:3,columns=Math.min(max,Math.max(1,requested));setColumns(columns,false);if(columns!==requested){url.searchParams.set('columns',String(columns));history.replaceState(history.state,'',url.pathname+url.search)}}document.addEventListener('click',event=>{const button=event.target.closest('[data-catalog-columns]');if(button)setColumns(button.dataset.catalogColumns)});window.addEventListener('popstate',syncColumns);window.addEventListener('resize',syncColumns);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',syncColumns,{once:true});else syncColumns()})();
</script>
